<?php
declare(strict_types=1);

const PUBLIC_STORE_STEP23_VERSION='1.0-complete';
function ps23_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ps23_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
function ps23_tables():array{return ['public_store_settings','public_order_requests','public_order_request_items','public_order_events','public_checkout_attempts','public_payment_requests','public_store_exports'];}
function ps23_db():PDO{static $pdo=null;if($pdo instanceof PDO)return $pdo;$host=getenv('DB_HOST')?:'127.0.0.1';$port=getenv('DB_PORT')?:'3306';$name=getenv('DB_NAME')?:'healthcare_wellness_club';$user=getenv('DB_USER')?:'root';$pass=getenv('DB_PASS');$pass=$pass===false?'':$pass;$pdo=new PDO("mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $pdo;}
function ps23_table(PDO $pdo,string $t):bool{$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');$s->execute([$t]);return(int)$s->fetchColumn()>0;}
function ps23_run_migration(PDO $pdo):void{$f=dirname(__DIR__,2).'/database/migrations/019_step23_public_storefront.sql';if(!is_file($f))throw new RuntimeException('STEP 23 migration missing.');$sql=(string)file_get_contents($f);foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql)?:[] as $q){$q=trim($q);if($q===''||preg_match('/^USE\s+/i',$q))continue;$q=preg_replace('/^(?:\s*--[^\r\n]*(?:\r?\n|$))+/', '',$q)??$q;$q=trim($q);if($q!=='')$pdo->exec($q);}}
function ps23_context(PDO $pdo):array{$r=$pdo->query("SELECT o.id organization_id,m.id market_id FROM organizations o JOIN product_markets m ON m.organization_id=o.id AND m.market_code='IN' WHERE o.organization_code='HWC-001' LIMIT 1")->fetch();if(!$r)throw new RuntimeException('Public product market unavailable.');return ['organization_id'=>(int)$r['organization_id'],'market_id'=>(int)$r['market_id']];}
function ps23_ensure(PDO $pdo):void{foreach(ps23_tables() as $t){if(!ps23_table($pdo,$t)){ps23_run_migration($pdo);break;}}foreach(ps23_tables() as $t)if(!ps23_table($pdo,$t))throw new RuntimeException('STEP 23 table missing: '.$t);$c=ps23_context($pdo);$s=$pdo->prepare("INSERT IGNORE INTO public_store_settings(organization_id,storefront_enabled,payment_mode,public_price_mode,checkout_note) VALUES(?,1,'review_only','mrp','Order request only. Final availability, eligible pricing, taxes and payment are confirmed by the club.')");$s->execute([$c['organization_id']]);if(ps23_table($pdo,'schema_meta')){$s=$pdo->prepare("INSERT INTO schema_meta(meta_key,meta_value) VALUES('public_store_step23_version',?) ON DUPLICATE KEY UPDATE meta_value=VALUES(meta_value)");$s->execute([PUBLIC_STORE_STEP23_VERSION]);}}
function ps23_settings(PDO $pdo,int $orgId):array{$s=$pdo->prepare('SELECT * FROM public_store_settings WHERE organization_id=?');$s->execute([$orgId]);return$s->fetch()?:[];}
function ps23_categories(PDO $pdo,int $orgId):array{$s=$pdo->prepare("SELECT id,category_name FROM product_categories WHERE organization_id=? AND status='active' ORDER BY sort_order,category_name");$s->execute([$orgId]);return$s->fetchAll();}
function ps23_catalog(PDO $pdo,int $orgId,string $q='',int $category=0):array{$where=["p.organization_id=?","p.status='active'","l.status='active'","v.status='active'","v.effective_from<=CURDATE()","v.effective_from=(SELECT MAX(v2.effective_from) FROM product_price_versions v2 WHERE v2.organization_id=v.organization_id AND v2.listing_id=v.listing_id AND v2.status='active' AND v2.effective_from<=CURDATE())"];$a=[$orgId];if($category>0){$where[]='p.category_id=?';$a[]=$category;}if(trim($q)!==''){$where[]='(p.product_name LIKE ? OR p.sku LIKE ? OR c.category_name LIKE ?)';$like='%'.trim($q).'%';array_push($a,$like,$like,$like);}$sql="SELECT p.id,p.sku,p.product_name,p.pack_size,p.pack_unit,p.category_id,c.category_name,l.id listing_id,v.id price_version_id,v.mrp,v.volume_points,v.effective_from,(SELECT image_url FROM product_images i WHERE i.product_id=p.id AND i.is_primary=1 AND i.verification_status='verified' ORDER BY i.id LIMIT 1) verified_image FROM products p JOIN product_categories c ON c.id=p.category_id JOIN product_market_listings l ON l.product_id=p.id AND l.organization_id=p.organization_id JOIN product_price_versions v ON v.listing_id=l.id AND v.organization_id=l.organization_id WHERE ".implode(' AND ',$where)." ORDER BY c.sort_order,p.product_name LIMIT 300";$s=$pdo->prepare($sql);$s->execute($a);$rows=$s->fetchAll();foreach($rows as &$r){$av=ps23_availability($pdo,$orgId,(int)$r['listing_id'],1);$r['availability_status']=$av['status'];$r['_sellable_qty']=$av['qty'];}unset($r);return$rows;}
function ps23_product(PDO $pdo,int $orgId,int $id):array{foreach(ps23_catalog($pdo,$orgId) as $r)if((int)$r['id']===$id)return$r;throw new RuntimeException('Product not found.');}
function ps23_availability(PDO $pdo,int $orgId,int $listingId,float $requested=1):array{if(!ps23_table($pdo,'inventory_product_settings')||!ps23_table($pdo,'inventory_batches'))return['status'=>'review','qty'=>null];$s=$pdo->prepare("SELECT COUNT(*) settings,SUM(track_stock=1) tracked FROM inventory_product_settings WHERE organization_id=? AND listing_id=?");$s->execute([$orgId,$listingId]);$r=$s->fetch()?:[];if((int)($r['settings']??0)===0||(int)($r['tracked']??0)===0)return['status'=>'review','qty'=>null];$s=$pdo->prepare("SELECT COALESCE(SUM(current_quantity),0) FROM inventory_batches WHERE organization_id=? AND listing_id=? AND status='active' AND current_quantity>0 AND (expiry_date IS NULL OR expiry_date>=CURDATE())");$s->execute([$orgId,$listingId]);$qty=(float)$s->fetchColumn();if($qty<=0)return['status'=>'unavailable','qty'=>0.0];return['status'=>$qty<$requested?'limited':'available','qty'=>$qty];}
function ps23_cart_quote(PDO $pdo,int $orgId,array $cart,string $mode):array{$mode=in_array($mode,['club_pickup','home_delivery'],true)?$mode:'club_pickup';$items=[];$subtotal=0.0;$vp=0.0;$hasNutrition=false;$seen=[];foreach($cart as $raw){$id=(int)($raw['product_id']??0);$qty=(int)($raw['qty']??0);if($id<=0||$qty<=0||$qty>20||isset($seen[$id]))continue;$seen[$id]=1;$p=ps23_product($pdo,$orgId,$id);$av=ps23_availability($pdo,$orgId,(int)$p['listing_id'],$qty);if($av['status']==='unavailable'||($av['qty']!==null&&(float)$av['qty']<$qty))throw new RuntimeException('One selected product is not available in the requested quantity.');$line=round((float)$p['mrp']*$qty,2);$lineVp=round((float)$p['volume_points']*$qty,3);$subtotal+=$line;$vp+=$lineVp;if(!in_array(strtoupper((string)$p['category_name']),['ART OF PROMOTION','APPLICATIONS'],true))$hasNutrition=true;$items[]=$p+['qty'=>$qty,'line_mrp'=>$line,'line_vp'=>$lineVp,'availability_status'=>$av['status']];}if(!$items)throw new RuntimeException('Add at least one valid product.');$delivery=($mode==='home_delivery'&&$hasNutrition&&$vp>0&&$vp<100)?118.0:0.0;return['items'=>$items,'subtotal_mrp'=>round($subtotal,2),'total_vp'=>round($vp,3),'delivery_charge'=>$delivery,'estimated_total'=>round($subtotal+$delivery,2),'delivery_mode'=>$mode];}
function ps23_mobile(string $v):string{$d=preg_replace('/\D+/','',$v)??'';if(strlen($d)>10&&str_starts_with($d,'91'))$d=substr($d,-10);return$d;}
function ps23_ip_hash(string $ip):string{$pepper=(string)(getenv('HWC_PUBLIC_FORM_PEPPER')?:'hwc-public-form-local');return hash('sha256',$pepper.'|'.$ip);}
function ps23_dup(string $mobile,string $email):?string{$m=ps23_mobile($mobile);$e=strtolower(trim($email));if($m!=='')return hash('sha256','mobile|'.$m);if($e!=='')return hash('sha256','email|'.$e);return null;}
function ps23_uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
function ps23_origin_ok(array $server):bool{$origin=trim((string)($server['HTTP_ORIGIN']??''));if($origin==='')return true;$oh=strtolower((string)(parse_url($origin,PHP_URL_HOST)?:''));$host=strtolower(preg_replace('/:\d+$/','',(string)($server['HTTP_HOST']??''))??'');return$oh!==''&&$host!==''&&hash_equals($host,$oh);}
function ps23_link_lead(PDO $pdo,int $orgId,string $name,string $mobile,string $email,string $note,?string $dup,string $ipHash,string $ua):?int{if(!ps23_table($pdo,'crm_leads')||!ps23_table($pdo,'crm_lead_sources'))return null;$pdo->prepare("INSERT INTO crm_lead_sources(organization_id,source_code,source_name,channel,is_active) VALUES(?,'PUBLIC-STORE','Public Product Store','website',1) ON DUPLICATE KEY UPDATE source_name=VALUES(source_name),is_active=1")->execute([$orgId]);$s=$pdo->prepare("SELECT id FROM crm_lead_sources WHERE organization_id=? AND source_code='PUBLIC-STORE' LIMIT 1");$s->execute([$orgId]);$source=(int)$s->fetchColumn();$leadId=0;if($dup){$s=$pdo->prepare("SELECT id FROM crm_leads WHERE organization_id=? AND duplicate_key_hash=? AND status='active' AND stage NOT IN ('converted','lost') ORDER BY id DESC LIMIT 1");$s->execute([$orgId,$dup]);$leadId=(int)$s->fetchColumn();}if($leadId<=0){$code='LEAD-'.date('Ymd-His').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$s=$pdo->prepare("INSERT INTO crm_leads(organization_id,lead_code,source_id,lead_type,full_name,mobile,email,message,stage,priority,consent_to_contact,duplicate_key_hash,submission_count,first_seen_at,last_seen_at,status) VALUES(?,?,?,'product',?,?,?,?,'new','normal',1,?,1,NOW(),NOW(),'active')");$s->execute([$orgId,$code,$source,$name,$mobile?:null,$email?:null,$note?:null,$dup]);$leadId=(int)$pdo->lastInsertId();}else{$pdo->prepare("UPDATE crm_leads SET submission_count=submission_count+1,last_seen_at=NOW(),lead_type='product' WHERE organization_id=? AND id=?")->execute([$orgId,$leadId]);}if(ps23_table($pdo,'crm_lead_activities'))$pdo->prepare("INSERT INTO crm_lead_activities(organization_id,lead_id,activity_type,subject,notes) VALUES(?,?,'public_store_order','Public product order request received',?)")->execute([$orgId,$leadId,$note?:null]);if(ps23_table($pdo,'crm_lead_submissions')){$s=$pdo->prepare("INSERT INTO crm_lead_submissions(organization_id,lead_id,source_id,submission_uuid,lead_type,full_name,mobile,email,message,page_path,ip_hash,user_agent,spam_status) VALUES(?,?,?,?, 'product',?,?,?,?, 'shop/checkout.php',?,?,'accepted')");$s->execute([$orgId,$leadId,$source,ps23_uuid(),$name,$mobile?:null,$email?:null,$note?:null,$ipHash,$ua?:null]);}return$leadId;}
function ps23_submit(PDO $pdo,array $in,array $server):array{ps23_ensure($pdo);$c=ps23_context($pdo);$orgId=$c['organization_id'];$set=ps23_settings($pdo,$orgId);if(empty($set['storefront_enabled']))throw new RuntimeException('Online product requests are temporarily unavailable.');if(!ps23_origin_ok($server))throw new RuntimeException('Request origin is not allowed.');$name=trim((string)($in['name']??''));$mobile=ps23_mobile((string)($in['mobile']??''));$email=strtolower(trim((string)($in['email']??'')));$address=trim((string)($in['address']??''));$postal=trim((string)($in['postal_code']??''));$note=trim((string)($in['note']??''));$consent=(string)($in['consent']??'')==='1';$hp=trim((string)($in['website']??''));$started=(int)($in['started_at']??0);$tooFast=$started>0&&((int)floor(microtime(true)*1000)-$started)<1500;$ipHash=ps23_ip_hash((string)($server['REMOTE_ADDR']??''));$ua=substr((string)($server['HTTP_USER_AGENT']??''),0,500);$cart=json_decode((string)($in['cart_json']??'[]'),true);if(!is_array($cart))$cart=[];$rate=$pdo->prepare("SELECT COUNT(*) FROM public_checkout_attempts WHERE organization_id=? AND ip_hash=? AND created_at>=DATE_SUB(NOW(),INTERVAL 1 HOUR)");$rate->execute([$orgId,$ipHash]);if((int)$rate->fetchColumn()>=8)throw new RuntimeException('Too many recent checkout attempts. Please try again later.');if($hp!==''||$tooFast){$pdo->prepare("INSERT INTO public_checkout_attempts(organization_id,ip_hash,attempt_status,reason_code,cart_line_count) VALUES(?,?,'blocked',?,?)")->execute([$orgId,$ipHash,$hp!==''?'honeypot':'too_fast',count($cart)]);return['ok'=>true,'message'=>'Thanks. Your request has been received.'];}if(strlen($name)<2||strlen($name)>190)throw new RuntimeException('Enter a valid name.');if(strlen($mobile)<10)throw new RuntimeException('Enter a valid mobile number.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');if(!$consent)throw new RuntimeException('Please allow the club to contact you about this order request.');if(count($cart)>30)throw new RuntimeException('Cart has too many product lines.');$quote=ps23_cart_quote($pdo,$orgId,$cart,(string)($in['delivery_mode']??'club_pickup'));if($quote['delivery_mode']==='home_delivery'&&strlen($address)<5)throw new RuntimeException('Enter a delivery address.');$dup=ps23_dup($mobile,$email);$token=bin2hex(random_bytes(24));$code='WEB-'.date('Ymd-His').'-'.strtoupper(substr(bin2hex(random_bytes(2)),0,4));$pdo->beginTransaction();try{$leadId=ps23_link_lead($pdo,$orgId,$name,$mobile,$email,$note,$dup,$ipHash,$ua);$s=$pdo->prepare("INSERT INTO public_order_requests(organization_id,order_code,lead_id,customer_name,mobile,email,address_text,postal_code,delivery_mode,subtotal_mrp,total_vp,delivery_charge,estimated_total,tax_status,order_status,payment_status,consent_to_contact,duplicate_key_hash,status_token_hash,ip_hash,user_agent,source_path,customer_note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'not_calculated','submitted','not_requested',1,?,?,?,?, 'shop/checkout.php',?)");$s->execute([$orgId,$code,$leadId,$name,$mobile,$email?:null,$address?:null,$postal?:null,$quote['delivery_mode'],$quote['subtotal_mrp'],$quote['total_vp'],$quote['delivery_charge'],$quote['estimated_total'],$dup,hash('sha256',$token),$ipHash,$ua?:null,$note?:null]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO public_order_request_items(organization_id,public_order_id,product_id,listing_id,price_version_id,stock_no,product_name_snapshot,quantity,unit_mrp,unit_vp,line_mrp,line_vp,availability_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)");foreach($quote['items'] as $it)$ins->execute([$orgId,$oid,$it['id'],$it['listing_id'],$it['price_version_id'],$it['sku'],$it['product_name'],$it['qty'],$it['mrp'],$it['volume_points'],$it['line_mrp'],$it['line_vp'],$it['availability_status']]);$pdo->prepare("INSERT INTO public_order_events(organization_id,public_order_id,event_type,new_status,note) VALUES(?,?,'submitted','submitted','Public order request captured; no payment collected.')")->execute([$orgId,$oid]);$pdo->prepare("INSERT INTO public_payment_requests(organization_id,public_order_id,payment_mode,amount,currency_code,payment_status) VALUES(?,?,?,?,'INR','not_requested')")->execute([$orgId,$oid,(string)($set['payment_mode']??'review_only'),$quote['estimated_total']]);$pdo->prepare("INSERT INTO public_checkout_attempts(organization_id,ip_hash,attempt_status,cart_line_count) VALUES(?,?,'accepted',?)")->execute([$orgId,$ipHash,count($quote['items'])]);$pdo->commit();return['ok'=>true,'message'=>'Your order request has been saved. The club will confirm availability, final payable amount and payment separately.','order_code'=>$code,'status_token'=>$token,'estimated_total'=>$quote['estimated_total']];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
function ps23_status(PDO $pdo,string $code,string $token):array{ps23_ensure($pdo);$c=ps23_context($pdo);$s=$pdo->prepare("SELECT id,order_code,delivery_mode,subtotal_mrp,total_vp,delivery_charge,estimated_total,tax_status,order_status,payment_status,created_at,updated_at FROM public_order_requests WHERE organization_id=? AND order_code=? AND status_token_hash=? LIMIT 1");$s->execute([$c['organization_id'],trim($code),hash('sha256',trim($token))]);$o=$s->fetch();if(!$o)throw new RuntimeException('Order request not found or tracking token is invalid.');$s=$pdo->prepare("SELECT stock_no,product_name_snapshot,quantity,unit_mrp,line_mrp FROM public_order_request_items WHERE organization_id=? AND public_order_id=? ORDER BY id");$s->execute([$c['organization_id'],$o['id']]);$o['items']=$s->fetchAll();$s=$pdo->prepare("SELECT event_type,new_status,note,created_at FROM public_order_events WHERE organization_id=? AND public_order_id=? ORDER BY id");$s->execute([$c['organization_id'],$o['id']]);$o['events']=$s->fetchAll();return$o;}
function ps23_seed_permissions(PDO $pdo,int $orgId):void{if(!ps23_table($pdo,'security_permissions')||!ps23_table($pdo,'security_role_permissions'))return;$defs=[['storefront.view','Public Store Orders: View','storefront','sensitive','View public product requests and storefront analytics.'],['storefront.manage','Public Store Orders: Manage','storefront','sensitive','Review public orders, link customers, change status and create internal quotes.'],['storefront.export','Public Store Orders: Export','storefront','sensitive','Export public order request data.']];$p=$pdo->prepare("INSERT INTO security_permissions(permission_code,permission_name,module_code,risk_level,description,is_active) VALUES(?,?,?,?,?,1) ON DUPLICATE KEY UPDATE permission_name=VALUES(permission_name),description=VALUES(description),is_active=1");foreach($defs as$d)$p->execute($d);$a=$pdo->prepare("INSERT INTO security_role_permissions(organization_id,role_code,permission_code,is_allowed) VALUES(?,'admin',?,1) ON DUPLICATE KEY UPDATE is_allowed=1");foreach($defs as$d)$a->execute([$orgId,$d[0]]);$m=$pdo->prepare("INSERT IGNORE INTO security_role_permissions(organization_id,role_code,permission_code,is_allowed) VALUES(?,'manager',?,1)");foreach($defs as$d)$m->execute([$orgId,$d[0]]);}
function ps23_admin_ensure(PDO $pdo):array{ps23_ensure($pdo);$c=ps23_context($pdo);ps23_seed_permissions($pdo,$c['organization_id']);return$c;}
function ps23_guard(PDO $pdo,string $perm):array{if(!function_exists('security_step17_current_user')||!function_exists('security_step17_has_permission'))throw new RuntimeException('Security engine unavailable.');$u=security_step17_current_user($pdo);if(!security_step17_has_permission($pdo,$perm,$u)){http_response_code(403);throw new RuntimeException('Storefront permission required: '.$perm);}return$u;}
function ps23_metrics(PDO $pdo,int $orgId):array{$s=$pdo->prepare("SELECT COUNT(*) total,SUM(order_status='submitted') submitted,SUM(order_status IN ('reviewing','confirmed')) active,SUM(order_status='quote_ready') quote_ready,SUM(order_status='cancelled') cancelled,COALESCE(SUM(CASE WHEN order_status<>'cancelled' THEN estimated_total ELSE 0 END),0) request_value FROM public_order_requests WHERE organization_id=?");$s->execute([$orgId]);return$s->fetch()?:[];}
function ps23_orders(PDO $pdo,int $orgId,string $status='all'):array{$w='organization_id=?';$a=[$orgId];$allowed=['submitted','reviewing','confirmed','quote_ready','converted','cancelled'];if(in_array($status,$allowed,true)){$w.=' AND order_status=?';$a[]=$status;}$s=$pdo->prepare("SELECT * FROM public_order_requests WHERE $w ORDER BY FIELD(order_status,'submitted','reviewing','confirmed','quote_ready','converted','cancelled'),created_at DESC LIMIT 500");$s->execute($a);return$s->fetchAll();}
function ps23_order(PDO $pdo,int $orgId,int $id):array{$s=$pdo->prepare('SELECT o.*,l.lead_code,c.customer_name,q.quote_code FROM public_order_requests o LEFT JOIN crm_leads l ON l.id=o.lead_id LEFT JOIN crm_customers c ON c.id=o.customer_id LEFT JOIN product_quotes q ON q.id=o.quote_id WHERE o.organization_id=? AND o.id=? LIMIT 1');$s->execute([$orgId,$id]);$o=$s->fetch();if(!$o)throw new RuntimeException('Public order request not found.');$s=$pdo->prepare('SELECT * FROM public_order_request_items WHERE organization_id=? AND public_order_id=? ORDER BY id');$s->execute([$orgId,$id]);$o['items']=$s->fetchAll();$s=$pdo->prepare('SELECT e.*,u.full_name actor_name FROM public_order_events e LEFT JOIN system_users u ON u.id=e.actor_user_id WHERE e.organization_id=? AND e.public_order_id=? ORDER BY e.id DESC');$s->execute([$orgId,$id]);$o['events']=$s->fetchAll();return$o;}
function ps23_set_status(PDO $pdo,int $orgId,int $id,string $new,string $note,int $uid):void{$allowed=['submitted','reviewing','confirmed','quote_ready','converted','cancelled'];if(!in_array($new,$allowed,true))throw new RuntimeException('Invalid order status.');$o=ps23_order($pdo,$orgId,$id);$old=(string)$o['order_status'];if($new==='converted'&&empty($o['quote_id']))throw new RuntimeException('Create an internal quote before marking this request converted.');$pdo->prepare('UPDATE public_order_requests SET order_status=?,internal_note=?,reviewed_by=?,reviewed_at=NOW() WHERE organization_id=? AND id=?')->execute([$new,trim($note)?:null,$uid,$orgId,$id]);$pdo->prepare('INSERT INTO public_order_events(organization_id,public_order_id,event_type,old_status,new_status,note,actor_user_id) VALUES(?,?,?,?,?,?,?)')->execute([$orgId,$id,'status_changed',$old,$new,trim($note)?:null,$uid]);}
function ps23_link_customer(PDO $pdo,int $orgId,int $id,int $customerId,int $uid):void{$s=$pdo->prepare('SELECT id FROM crm_customers WHERE organization_id=? AND id=? AND status=\'active\'');$s->execute([$orgId,$customerId]);if(!(int)$s->fetchColumn())throw new RuntimeException('Selected customer is not active.');$pdo->prepare('UPDATE public_order_requests SET customer_id=? WHERE organization_id=? AND id=?')->execute([$customerId,$orgId,$id]);$pdo->prepare("INSERT INTO public_order_events(organization_id,public_order_id,event_type,note,actor_user_id) VALUES(?,?,'customer_linked','Customer linked explicitly by staff.',?)")->execute([$orgId,$id,$uid]);}
function ps23_create_quote(PDO $pdo,int $orgId,int $id,int $uid):int{$o=ps23_order($pdo,$orgId,$id);if(!empty($o['quote_id']))return(int)$o['quote_id'];if((string)$o['order_status']==='cancelled')throw new RuntimeException('Cancelled request cannot create a quote.');$ctx=ps23_context($pdo);$code='QWEB-'.date('YmdHis').'-'.random_int(100,999);$pdo->beginTransaction();try{$s=$pdo->prepare("INSERT INTO product_quotes(organization_id,market_id,quote_code,customer_name,customer_type,pricing_tier_code,subtotal_mrp,payable_amount,saving_amount,total_vp,delivery_charge,grand_total,status,notes) VALUES(?,?,?,?, 'public','MRP',?,?,0,?,?,?,'saved',?)");$s->execute([$orgId,$ctx['market_id'],$code,$o['customer_name'],$o['subtotal_mrp'],$o['subtotal_mrp'],$o['total_vp'],$o['delivery_charge'],$o['estimated_total'],'Created from public order request '.$o['order_code'].'. Final eligibility/tax/payment remains staff-confirmed.']);$qid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO product_quote_items(quote_id,product_id,listing_id,price_version_id,stock_no,product_name,quantity,unit_mrp,unit_price,unit_vp,line_mrp,line_price,line_vp) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($o['items'] as$it)$ins->execute([$qid,$it['product_id'],$it['listing_id'],$it['price_version_id'],$it['stock_no'],$it['product_name_snapshot'],$it['quantity'],$it['unit_mrp'],$it['unit_mrp'],$it['unit_vp'],$it['line_mrp'],$it['line_mrp'],$it['line_vp']]);$pdo->prepare("UPDATE public_order_requests SET quote_id=?,order_status='quote_ready',reviewed_by=?,reviewed_at=NOW() WHERE organization_id=? AND id=?")->execute([$qid,$uid,$orgId,$id]);$pdo->prepare("INSERT INTO public_order_events(organization_id,public_order_id,event_type,old_status,new_status,note,actor_user_id) VALUES(?,?,'quote_created',?,'quote_ready',?,?)")->execute([$orgId,$id,$o['order_status'],'Internal MRP quote '.$code.' created.',$uid]);$pdo->commit();return$qid;}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
